window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5efe4018d960c140"]={"versions": [{"id": "FIG-5efe4018d960c140", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR Basic Software Module Description Template (BSWMD Template). Es spezifiziert die Metamodell-Struktur für Service-Bedarfe (<code>ServiceNeeds</code>) aus dem Paket <code>CommonStructure</code> mit Spezialisierung auf Diagnose- und OBD-Anwendungsfälle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Vererbungshierarchie ausgehend von der abstrakten Klasse <code>ServiceNeeds</code> (spezialisiert von <code>Identifiable</code>):</p>\n<ul class=\"fig-list\"><li><strong>Abgeleitete Klassen von <code>ServiceNeeds</code></strong>:\n<ul class=\"fig-list\"><li><code>DiagnosticEventNeeds</code>: Spezifiziert den Bedarf bezüglich Diagnose-Events.\n</li><li><code>FunctionInhibitionNeeds</code>: Spezifiziert Bedarfe zur Funktionsdeaktivierung (FIM).\n</li><li><code>DiagnosticCommunicationNeeds</code>: Spezifiziert Kommunikationsbedarfe für die Diagnose.\n</li><li><code>ObdPidServiceNeeds</code>: OBD Parameter Identifier Service-Bedarf mit Attributen <code>+ dataLength: Int</code>, <code>+ parameterId: Int</code>, <code>+ standard: String</code>.\n</li><li><code>ObdRatioServiceNeeds</code>: IUMPR-Verhältnisbedarfe mit Attributen <code>+ connectionType: ObdRatioConnectionKind</code>, <code>+ iumprGroup: String</code>.\n</li><li><code>ObdInfoServiceNeeds</code>: OBD-Info-Service-Bedarf mit Attributen <code>+ dataLength: Int</code>, <code>+ infoType: Int</code>.\n</li><li><code>ObdMonitorServiceNeeds</code>: OBD-Monitor-Bedarf mit Attributen <code>+ onBoardMonitorId: Int</code>, <code>+ testId: Int</code>, <code>+ unitAndScalingId: Int</code>.\n</li><li><code>ObdControlServiceNeeds</code>: OBD-Steuerungs-Bedarf mit Attribut <code>+ testId: Int</code>.\n</li></ul>\n</li><li><strong>Assoziationen</strong>:\n<ul class=\"fig-list\"><li><code>ObdRatioServiceNeeds</code> referenziert über die gerichtete Assoziation <code>+rateBasedMonitoredEvent</code> genau <code>1</code> Instanz von <code>DiagnosticEventNeeds</code>.\n</li><li><code>ObdRatioServiceNeeds</code> referenziert über die gerichtete Assoziation <code>+usedFid</code> <code>0..1</code> Instanzen von <code>FunctionInhibitionNeeds</code>.\n</li></ul>\n</li><li><strong>Enumerationen</strong>:\n<ul class=\"fig-list\"><li><code>«enumeration» ObdRatioConnectionKind</code> mit den Literalen <code>apiUse</code> und <code>observer</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Assoziationen drücken strukturelle Abhängigkeiten zur Konfigurationszeit aus: Ein <code>ObdRatioServiceNeeds</code> verknüpft ein überwachtes Diagnose-Event (<code>DiagnosticEventNeeds</code>) mit einer optionalen Funktionshemmungs-ID (<code>FunctionInhibitionNeeds</code>), um Raten-basierte OBD-Überwachungen im Diagnosestack (Dem/Fim) aufzusetzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen definieren die formale XML-Metamodell-Beschreibung für BSW-Module zur Bedarfsanmeldung gegenüber dem Diagnostic Event Manager (Dem) und Function Inhibition Manager (FiM). Bei Attributen vom Typ <code>Int</code> und <code>String</code> sowie der Enumeration <code>ObdRatioConnectionKind</code> müssen die entsprechenden Konfigurationswerte im BSW-Modul-Deskriptor typkonform deklariert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e583c097c2ab201d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR Basic Software Module Description Template (BSWMD Template). Es spezifiziert die Metamodell-Struktur für Service-Bedarfe (<code>ServiceNeeds</code>) aus dem Paket <code>CommonStructure</code> mit Spezialisierung auf Diagnose- und OBD-Anwendungsfälle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Vererbungshierarchie ausgehend von der abstrakten Klasse <code>ServiceNeeds</code> (spezialisiert von <code>Identifiable</code>):</p>\n<ul class=\"fig-list\"><li><strong>Abgeleitete Klassen von <code>ServiceNeeds</code></strong>:\n<ul class=\"fig-list\"><li><code>DiagnosticEventNeeds</code>: Spezifiziert den Bedarf bezüglich Diagnose-Events.\n</li><li><code>FunctionInhibitionNeeds</code>: Spezifiziert Bedarfe zur Funktionsdeaktivierung (FIM).\n</li><li><code>DiagnosticCommunicationNeeds</code>: Spezifiziert Kommunikationsbedarfe für die Diagnose.\n</li><li><code>ObdPidServiceNeeds</code>: OBD Parameter Identifier Service-Bedarf mit Attributen <code>+ dataLength :Integer</code>, <code>+ parameterId :Integer</code>, <code>+ standard :String</code>.\n</li><li><code>ObdRatioServiceNeeds</code>: IUMPR-Verhältnisbedarfe mit Attributen <code>+ connectionType :ObdRatioConnectionKind</code>, <code>+ iumprGroup :String</code>.\n</li><li><code>ObdInfoServiceNeeds</code>: OBD-Info-Service-Bedarf mit Attributen <code>+ dataLength :Integer</code>, <code>+ infoType :Integer</code>.\n</li><li><code>ObdMonitorServiceNeeds</code>: OBD-Monitor-Bedarf mit Attributen <code>+ onBoardMonitorId :Integer</code>, <code>+ testId :Integer</code>, <code>+ unitAndScalingId :Integer</code>.\n</li><li><code>ObdControlServiceNeeds</code>: OBD-Steuerungs-Bedarf mit Attribut <code>+ testId :Integer</code>.\n</li></ul>\n</li><li><strong>Assoziationen</strong>:\n<ul class=\"fig-list\"><li><code>ObdRatioServiceNeeds</code> referenziert über die gerichtete Assoziation <code>+rateBasedMonitoredEvent</code> genau <code>1</code> Instanz von <code>DiagnosticEventNeeds</code>.\n</li><li><code>ObdRatioServiceNeeds</code> referenziert über die gerichtete Assoziation <code>+usedFid</code> <code>0..1</code> Instanzen von <code>FunctionInhibitionNeeds</code>.\n</li></ul>\n</li><li><strong>Enumerationen</strong>:\n<ul class=\"fig-list\"><li><code>«enumeration» ObdRatioConnectionKind</code> mit den Literalen <code>apiUse</code> und <code>observer</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Assoziationen drücken strukturelle Abhängigkeiten zur Konfigurationszeit aus: Ein <code>ObdRatioServiceNeeds</code> verknüpft ein überwachtes Diagnose-Event (<code>DiagnosticEventNeeds</code>) mit einer optionalen Funktionshemmungs-ID (<code>FunctionInhibitionNeeds</code>), um Raten-basierte OBD-Überwachungen im Diagnosestack (Dem/Fim) aufzusetzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen definieren die formale XML-Metamodell-Beschreibung für BSW-Module zur Bedarfsanmeldung gegenüber dem Diagnostic Event Manager (Dem) und Function Inhibition Manager (FiM). Bei Attributen vom Typ <code>Integer</code> und <code>String</code> sowie der Enumeration <code>ObdRatioConnectionKind</code> müssen die entsprechenden Konfigurationswerte im BSW-Modul-Deskriptor typkonform deklariert werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5efe4018d960c140", "to": "FIG-e583c097c2ab201d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Datentyp der ganzzahligen Attribute in <code>ObdPidServiceNeeds</code> (<code>dataLength</code>, <code>parameterId</code>), <code>ObdInfoServiceNeeds</code> (<code>dataLength</code>, <code>infoType</code>), <code>ObdMonitorServiceNeeds</code> (<code>onBoardMonitorId</code>, <code>testId</code>, <code>unitAndScalingId</code>) und <code>ObdControlServiceNeeds</code> (<code>testId</code>) von <code>Int</code> auf <code>Integer</code> typisiert.\n</li></ul>"}]};
